1	import { describe, test, expect, vi, beforeEach } from 'vitest';
2	import { renderHook } from '@testing-library/react';
3	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
4	import { useCountryConfig } from './useCountryConfig';
5	import { COUNTRIES } from '../config/countries';
6	
7	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
8	  default: vi.fn(),
9	}));
10	
11	const mockUseMultiSite = vi.mocked(useMultiSite);
12	
13	function mockSite(siteId: string, localeId: string): void {
14	  mockUseMultiSite.mockReturnValue({ site: { id: siteId }, locale: { id: localeId } });
15	}
16	
17	describe('useCountryConfig', () => {
18	  beforeEach(() => {
19	    vi.clearAllMocks();
20	  });
21	
22	  test('returns AU config for ZimmermannAU + en', () => {
23	    mockSite('ZimmermannAU', 'en');
24	    const { result } = renderHook(() => useCountryConfig());
25	    expect(result.current).toBe(COUNTRIES.au);
26	    expect(result.current.checkoutOwner).toBe('sfcc');
27	    expect(result.current.globalEPricing).toBe(false);
28	  });
29	
30	  test('returns UK config for ZimmermannUK + en-GB (not en-eu)', () => {
31	    mockSite('ZimmermannUK', 'en-GB');
32	    const { result } = renderHook(() => useCountryConfig());
33	    expect(result.current).toBe(COUNTRIES.uk);
34	    expect(result.current.sfccSiteId).toBe('ZimmermannUK');
35	  });
36	
37	  test('returns en-eu config for ZimmermannEU + en-GB (not uk)', () => {
38	    mockSite('ZimmermannEU', 'en-GB');
39	    const { result } = renderHook(() => useCountryConfig());
40	    expect(result.current).toBe(COUNTRIES['en-eu']);
41	    expect(result.current.sfccSiteId).toBe('ZimmermannEU');
