69	
70	  test('returns ME config for ZimmermannME + en-AE', () => {
71	    mockSite('ZimmermannME', 'en-AE');
72	    const { result } = renderHook(() => useCountryConfig());
73	    expect(result.current).toBe(COUNTRIES['en-ae']);
74	    expect(result.current.checkoutOwner).toBe('global-e');
75	  });
76	
77	  test('falls back to AU default for unrecognised site ID', () => {
78	    mockSite('RefArch', 'en-US');
